import itertools, random

# Let's try to find a graph using random 4-regular graphs and compute chromatic number exactly via backtracking.

def chromatic_number(edges, n):
    # adjacency bitmask
    adj = [0]*n
    for u,v in edges:
        adj[u] |= 1<<v
        adj[v] |= 1<<u
    # order vertices by degree descending for backtracking
    order = sorted(range(n), key=lambda x: bin(adj[x]).count('1'), reverse=True)
    # color assignment
    colors = [-1]*n
    # precompute neighbor colors? just check adjacency
    def dfs(idx):
        if idx == n:
            return True
        v = order[idx]
        # compute used colors by neighbors
        used = 0
        mask = adj[v]
        for u in range(n):
            if mask & (1<<u):
                if colors[u] != -1:
                    used |= 1<<colors[u]
        # try colors 0..max_color
        # we want to find minimal, but here we just want to know if <=4 and >=3
        # For speed, we can just try up to 4.
        for c in range(4):
            if not (used & (1<<c)):
                colors[v] = c
                if dfs(idx+1):
                    return True
                colors[v] = -1
        return False
    # check if 4-colorable
    four_colorable = dfs(0)
    if not four_colorable:
        return 5  # >4
    # check if 2-colorable (bipartite)
    # BFS
    color2 = [-1]*n
    from collections import deque
    bip = True
    for i in range(n):
        if color2[i] == -1:
            color2[i] = 0
            dq = deque([i])
            while dq:
                u = dq.popleft()
                for v in range(n):
                    if adj[u] & (1<<v):
                        if color2[v] == -1:
                            color2[v] = color2[u]^1
                            dq.append(v)
                        elif color2[v] == color2[u]:
                            bip = False
                            break
                if not bip:
                    break
        if not bip:
            break
    if bip:
        return 2
    # check if 3-colorable
    colors = [-1]*n
    def dfs3(idx):
        if idx == n:
            return True
        v = order[idx]
        used = 0
        mask = adj[v]
        for u in range(n):
            if mask & (1<<u):
                if colors[u] != -1:
                    used |= 1<<colors[u]
        for c in range(3):
            if not (used & (1<<c)):
                colors[v] = c
                if dfs3(idx+1):
                    return True
                colors[v] = -1
        return False
    three_colorable = dfs3(0)
    if three_colorable:
        return 3
    else:
        return 4

